CREATE TABLE IF NOT EXISTS schema_migration (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE filament_product (id TEXT PRIMARY KEY, brand TEXT NOT NULL, name TEXT NOT NULL, material TEXT NOT NULL, subtype TEXT NOT NULL, color_name TEXT NOT NULL, color_hex TEXT NOT NULL, color_code TEXT NOT NULL, net_mg INTEGER NOT NULL CHECK(net_mg>0), signature TEXT NOT NULL UNIQUE);
CREATE TABLE spool (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES filament_product(id), remaining_mg INTEGER NOT NULL CHECK(remaining_mg>=0), empty_mg INTEGER, price_cents INTEGER, purchased_at TEXT, opened_at TEXT, location TEXT NOT NULL, notes TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX spool_product ON spool(product_id);
CREATE TABLE printer (id TEXT PRIMARY KEY, name TEXT NOT NULL, model TEXT NOT NULL, serial TEXT UNIQUE, connection TEXT NOT NULL, last_sync_at TEXT, status TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE printer_extruder (id TEXT PRIMARY KEY, printer_id TEXT NOT NULL REFERENCES printer(id), name TEXT NOT NULL, mapping_verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE printer_slot (id TEXT PRIMARY KEY, printer_id TEXT NOT NULL REFERENCES printer(id), extruder_id TEXT REFERENCES printer_extruder(id), name TEXT NOT NULL, kind TEXT NOT NULL);
CREATE TABLE slot_assignment (id TEXT PRIMARY KEY, slot_id TEXT NOT NULL REFERENCES printer_slot(id), spool_id TEXT NOT NULL REFERENCES spool(id), assigned_at TEXT NOT NULL, unassigned_at TEXT);
CREATE UNIQUE INDEX active_slot ON slot_assignment(slot_id) WHERE unassigned_at IS NULL;
CREATE UNIQUE INDEX active_spool ON slot_assignment(spool_id) WHERE unassigned_at IS NULL;
CREATE TABLE print_job (id TEXT PRIMARY KEY, name TEXT NOT NULL, printer_id TEXT REFERENCES printer(id), source TEXT NOT NULL, external_id TEXT, external_device_id TEXT NOT NULL DEFAULT '', started_at TEXT, finished_at TEXT, duration_seconds INTEGER, print_status TEXT NOT NULL, review_status TEXT NOT NULL, total_mg INTEGER, incomplete INTEGER NOT NULL, notes TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, slot_snapshot TEXT NOT NULL DEFAULT '[]', thumbnail TEXT, created_at TEXT NOT NULL, UNIQUE(source,external_device_id,external_id));
CREATE INDEX job_review_status ON print_job(review_status,created_at);
CREATE TABLE print_job_material (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES print_job(id), material TEXT, color_hex TEXT, color_name TEXT, suggested_mg INTEGER, source TEXT NOT NULL, source_slot TEXT, source_nozzle TEXT);
CREATE TABLE job_review (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES print_job(id), request_id TEXT NOT NULL UNIQUE, payload_hash TEXT NOT NULL, kind TEXT NOT NULL, notes TEXT NOT NULL, created_at TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE review_allocation (id TEXT PRIMARY KEY, review_id TEXT NOT NULL REFERENCES job_review(id), material_id TEXT NOT NULL REFERENCES print_job_material(id), spool_id TEXT NOT NULL REFERENCES spool(id), amount_mg INTEGER NOT NULL CHECK(amount_mg>=0), source TEXT NOT NULL);
CREATE TABLE inventory_transaction (id TEXT PRIMARY KEY, spool_id TEXT NOT NULL REFERENCES spool(id), job_id TEXT REFERENCES print_job(id), review_id TEXT REFERENCES job_review(id), kind TEXT NOT NULL, delta_mg INTEGER NOT NULL, before_mg INTEGER NOT NULL CHECK(before_mg>=0), after_mg INTEGER NOT NULL CHECK(after_mg>=0), source TEXT NOT NULL, notes TEXT NOT NULL, created_at TEXT NOT NULL, cost_cents REAL, CHECK(after_mg=before_mg+delta_mg));
CREATE INDEX transaction_spool ON inventory_transaction(spool_id,created_at);
CREATE INDEX transaction_job ON inventory_transaction(job_id);
CREATE TABLE sync_state (id TEXT PRIMARY KEY, status TEXT NOT NULL, last_success_at TEXT, last_attempt_at TEXT, error TEXT, cursor TEXT);
INSERT INTO sync_state(id,status) VALUES('bambu_cloud','unavailable');
CREATE TABLE integration_config (id TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, configuration TEXT NOT NULL DEFAULT '{}');
INSERT INTO integration_config(id) VALUES('bambu_cloud');
CREATE TABLE settings (id TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES('preferences','{"lowStockMg":150000,"locale":"zh-CN","timezone":"Asia/Shanghai"}');
